(function(){
  const st = window.__store.getState();
  const fp = st.floorPlan;
  const byId = new Map(fp.walls.map(w => [w.id, w]));
  const ext = fp.extent || [12.55, 9.25];
  const cx = ext[0]/2, cz = ext[1]/2;
  const clamp = (v,lo,hi)=>Math.min(hi,Math.max(lo,v));
  const tf = (op)=>{ const wall=byId.get(op.wallId); if(!wall) return null; const dx=wall.end[0]-wall.start[0], dz=wall.end[1]-wall.start[1]; const len=Math.hypot(dx,dz); if(len<1e-6) return null; const ux=dx/len,uz=dz/len; const c=op.offset+op.width/2; const wx=wall.start[0]+ux*c, wz=wall.start[1]+uz*c; let rotation=-Math.atan2(dz,dx); const nx=-uz,nz=ux; if((cx-wx)*nx+(cz-wz)*nz<0) rotation+=Math.PI; return { position:[wx,wz], rotation }; };
  const items = st.items.slice();
  const have = new Set(items.filter(i=>i.defId==='window-mesh-screen').map(i=>i.id));
  for (const op of fp.openings) {
    if (op.kind!=='window') continue;
    const id = 'mesh-'+op.id; if (have.has(id)) continue;
    const t = tf(op); if(!t) continue;
    items.push({ id, defId:'window-mesh-screen', position:t.position, rotation:t.rotation, props:{ width: clamp(op.width+0.06,0.4,3.4), sillY: clamp(op.sill,0,2.4), topY: clamp(op.head,0.3,3.2), density:'fine' } });
  }
  // Add a covered litter box in the service yard (satisfies the cat litter req).
  const sy = fp.rooms.find(r=>r.id==='serviceYard') || fp.rooms[0];
  if (sy) items.push({ id:'litter-p6', defId:'litter-box', position:[sy.origin[0]+0.6, sy.origin[1]+sy.depth-0.4], rotation:0, props:{ style:'covered' } });
  // Add a dog bed (satisfies the dog rest-area req).
  const ld = fp.rooms.find(r=>r.id==='livingDining') || fp.rooms[0];
  if (ld) items.push({ id:'dogbed-p6', defId:'dog-bed-orthopedic', position:[ld.origin[0]+0.7, ld.origin[1]+0.8], rotation:0, props:{} });
  st.setItems(items);
  console.log('all windows meshed + litter + dog bed added');
})()
